employee_amount:
const employment = ctx.subject.employment;
// One month's runs are one month of wages: what an earlier run of this month paid is in the balance.
const month = get(ctx, 'balances.month', {});
const paidMonth = String(get(ctx.run, 'pay_date', ctx.run.salary_coverage.from)).slice(0, 7);
const heldIn = (code) => (Object.hasOwn(month, paidMonth + '.' + code) ? Number(month[paidMonth + '.' + code]) : 0);
// A whole-month salary already in this pay month is another wage month's or another employer's: this run stands alone.
const coverage = ctx.run.salary_coverage;
const wholeMonth =
	String(coverage.from) === String(month_start(coverage.from)) && String(coverage.to) === String(month_end(coverage.from));
const separate = get(ctx.run, 'kind', '') !== 'OFF_CYCLE' && wholeMonth && heldIn('BASIC') > 0;
const before = (code) => (separate ? 0 : heldIn(code));
// Ahead of the month's salary an off-cycle run sits on the contract's month, so each run shows its own share.
const under = get(ctx.run, 'kind', '') === 'OFF_CYCLE' && before('AWARDS') === 0 ? ctx.day_rate * ctx.lookup.monthly_divisor : 0;
// s.2: overtime and gratuity sit between AWARDS and ORDINARY_WAGES; rest-day and holiday work within normal hours stay in.
const paid = Math.max(
	0,
	ctx.subtotals.ADDITIONAL_WAGES + before('ADDITIONAL_WAGES') - ctx.subtotals.ORDINARY_WAGES - before('ORDINARY_WAGES') + ctx.subtotals.AWARDS + before('AWARDS')
);
const dob = get(employment, 'payroll.date_of_birth', '');
const age = age_on(dob, add_days(ctx.run.salary_coverage.from, -1));
const owed = (w) => {
if (age >= ctx.lookup.senior_age || w <= ctx.lookup.minimum_chargeable) return 0;
if (w > ctx.lookup.table_ceiling) {
 const statutory = round(w * ctx.lookup.employee_rate, ctx.lookup.minor_unit, 'HALF_UP');
 return Math.max(statutory, round(w * get(employment, 'employee_extension_data.facts.statutory.EPF.elections.employee_rate', 0), ctx.lookup.whole_unit, 'UP'));
}
const band = w <= ctx.lookup.lower_rate_ceiling ? round(w, ctx.lookup.lower_salary_step, 'UP') : round(w, ctx.lookup.hundred_units, 'UP');
const statutory = round(band * ctx.lookup.employee_rate, ctx.lookup.whole_unit, 'UP');
return Math.max(statutory, round(w * get(employment, 'employee_extension_data.facts.statutory.EPF.elections.employee_rate', 0), ctx.lookup.whole_unit, 'UP'));
};
return Math.max(0, owed(paid + under) - owed(under) - before('EPF.employee'));

